fragment:

























      identity





<set-variable name="straikerRawBody" value="@{
    return context.Request.Body?.As(preserveContent: true) ?? "";
}" />













        application/json

      @("{\"error\":{\"message\":\"Streaming (stream=true) is not supported on this guarded route. Retry with stream=false, or use a route with straikerStreamingPolicy=allow-unscanned.\",\"code\":\"streaming_not_supported\"}}")










        application/json

      @("{\"error\":{\"message\":\"Request body exceeds the guarded-route size limit.\",\"code\":\"payload_too_large\"}}")





<set-variable name="straikerAppId" value="@{
    var mode = (string)context.Variables["straikerIdentityMode"];
    if (mode == "jwt") {
        var jwt = context.Variables.GetValueOrDefault("validatedJwt", null);
        if (jwt != null) {
            foreach (var c in new[] { "app_displayname", "azp", "appid" }) {
                if (jwt.Claims.ContainsKey(c) && jwt.Claims[c].Length > 0 && !string.IsNullOrEmpty(jwt.Claims[c][0])) { return jwt.Claims[c][0]; }
            }
        }
    }
    if (mode == "subscription" && context.Subscription != null) {
        return "apim-sub-" + context.Subscription.Id;
    }
    var hdr = context.Request.Headers.GetValueOrDefault("x-app-id", "");
    if (!string.IsNullOrEmpty(hdr)) { return hdr; }
    return (string)context.Variables["straikerSource"];
}" />

<set-variable name="straikerUserName" value="@{
    var mode = (string)context.Variables["straikerIdentityMode"];
    if (mode == "jwt") {
        var jwt = context.Variables.GetValueOrDefault("validatedJwt", null);
        if (jwt != null) {
            foreach (var c in new[] { "email", "preferred_username", "sub" }) {
                if (jwt.Claims.ContainsKey(c) && jwt.Claims[c].Length > 0 && !string.IsNullOrEmpty(jwt.Claims[c][0])) { return jwt.Claims[c][0]; }
            }
        }
    }
    var hdr = context.Request.Headers.GetValueOrDefault("x-user-name", "");
    if (!string.IsNullOrEmpty(hdr)) { return hdr; }
    var b = (JObject)context.Variables["straikerReqBody"];
    if (b["user"] != null && b["user"].Type == JTokenType.String) { return (string)b["user"]; }
    return "apim";
}" />
<set-variable name="straikerUserRole" value="@{
    var mode = (string)context.Variables["straikerIdentityMode"];
    if (mode == "jwt") {
        var jwt = context.Variables.GetValueOrDefault("validatedJwt", null);
        if (jwt != null && jwt.Claims.ContainsKey("roles") && jwt.Claims["roles"].Length > 0) { return jwt.Claims["roles"][0]; }
    }
    return context.Request.Headers.GetValueOrDefault("x-user-role", "public");
}" />
















    <retry condition="@(context.Variables.GetValueOrDefault("straikerPreResp", null) == null
                      || context.Variables.GetValueOrDefault("straikerPreResp").StatusCode >= 500)"
           count="1" interval="1" first-fast-retry="true">

        @((string)context.Variables["straikerWebhookUrl"])
        POST

          @("Bearer " + (string)context.Variables["straikerApiKey"])


          application/json


          @((string)context.Variables["straikerWebhookFormat"])


          true

        @{
            var envelope = new JObject {
                ["eventType"] = "pre_call",
                ["request"] = new JObject {
                    ["body"] = (JObject)context.Variables["straikerReqBody"],
                    ["text"] = (string)context.Variables["straikerPrompt"]
                },
                ["userInfo"] = new JObject {
                    ["id"]   = (string)context.Variables["straikerUserName"],
                    ["role"] = (string)context.Variables["straikerUserRole"]
                },
                ["consumer"] = new JObject {
                    ["appId"]     = (string)context.Variables["straikerAppId"],
                    ["name"]      = (string)context.Variables["straikerAppDisplayName"],
                    ["custom_id"] = context.Subscription != null ? context.Subscription.Id : ""
                },
                ["aiContext"] = new JObject {
                    ["llm_format"] = (string)context.Variables["straikerLlmFormat"],
                    ["model"] = new JObject {
                        ["name"] = (string)(((JObject)context.Variables["straikerReqBody"])["model"] ?? "unknown")
                    }
                },
                ["metadata"] = new JObject {
                    ["session_id"] = (string)context.Variables["straikerSessionId"],
                    ["trace_id"]   = context.Request.Headers.GetValueOrDefault("x-trace-id", ""),
                    ["client_ip"]  = context.Request.IpAddress ?? "127.0.0.1",
                    ["gateway"]    = "azure-apim"
                }
            };
            return envelope.ToString(Newtonsoft.Json.Formatting.None);
        }




    <set-variable name="straikerAction" value="@{
        var r = context.Variables.GetValueOrDefault("straikerPreResp", null);
        if (r == null || r.StatusCode != 200) { return "__unavailable__"; }
        try {
            var body = r.Body.As(preserveContent: true);
            var a = body["action"];
            if (a == null || a.Type != JTokenType.String) { return "__unavailable__"; }
            return ((string)a).ToLowerInvariant();
        } catch { return "__unavailable__"; }
    }" />
    <set-variable name="straikerTurnId" value="@{
        var r = context.Variables.GetValueOrDefault("straikerPreResp", null);
        if (r == null || r.StatusCode != 200) { return ""; }
        try {
            var body = r.Body.As(preserveContent: true);
            return (string)(body["turn_id"] ?? body["turnId"] ?? "");
        } catch { return ""; }
    }" />







            application/json


            block

          @{
              var b = (JObject)context.Variables["straikerReqBody"];
              var stub = new JObject {
                  ["id"] = "chatcmpl-straiker-blocked",
                  ["object"] = "chat.completion",
                  ["created"] = (long)(context.Timestamp - new DateTime(1970, 1, 1)).TotalSeconds,
                  ["model"] = (string)(b["model"] ?? "unknown"),
                  ["choices"] = new JArray {
                      new JObject {
                          ["index"] = 0,
                          ["message"] = new JObject {
                              ["role"] = "assistant",
                              ["content"] = "I'm sorry, I'm unable to process that request."
                          },
                          ["finish_reason"] = "stop"
                      }
                  },
                  ["usage"] = new JObject {
                      ["prompt_tokens"] = 0, ["completion_tokens"] = 0, ["total_tokens"] = 0
                  }
              };
              return stub.ToString(Newtonsoft.Json.Formatting.None);
          }







            application/json

          @{
              var err = new JObject {
                  ["error"] = new JObject {
                      ["message"] = "Straiker: request blocked by policy (pre-call)",
                      ["turn_id"] = (string)context.Variables["straikerTurnId"],
                      ["code"]    = "403"
                  }
              };
              return err.ToString(Newtonsoft.Json.Formatting.None);
          }






            application/json

          @("{\"error\":{\"message\":\"Straiker unavailable\",\"code\":\"503\"}}")
